def compute_average_size(object_sizes, num_bins):
    total_size = sum(object_sizes)
    return total_size / num_bins

def compute_split_size_bound(original_task_size):
    # This is a mathematical inequality, not a direct algorithm.
    # It represents a property of the splitting mechanism.
    return 2 * (1 - (1 - original_task_size)**0.5)

def compute_split_penalty_bound(original_task_size):
    # This is a mathematical inequality.
    return compute_split_size_bound(original_task_size) - original_task_size

def compute_split_sum_size_bound(original_task_size):
    # This is a mathematical inequality.
    return 2 * (1 - (1 - original_task_size)**0.5)
